VALUES
  ('q1000000-0000-0000-0000-000000000001', 'e1000000-0000-0000-0000-000000000001', 's1000000-0000-0000-0000-000000000001', 't1000000-0000-0000-0000-000000000001', 'PYQ', '[UPSC CSE 2013] Under which Article of the Constitution of India is the Right to Privacy protected as an intrinsic part of the Right to Life and Personal Liberty?', 'Article 14', 'Article 21', 'Article 19', 'Article 29', 'B', '{"why":"In Justice K.S. Puttaswamy (2017), a 9-judge bench held that Right to Privacy is protected under Article 21.","concept":"Article 21 & K.S. Puttaswamy Judgment (2017)","exam_perspective":"UPSC Prelims tests core conceptual clarity and negative exclusions across constitutional, ecological, and economic dimensions.","remember":"Privacy = Life & Personal Liberty = Article 21.","related_concept":"Article 19(1)(a), Maneka Gandhi case (1978)"}'::jsonb, 'easy', 2013, 'Civil Services (Preliminary) GS Paper-I', 'approved'),
  ('q1000000-0000-0000-0000-000000000002', 'e1000000-0000-0000-0000-000000000001', 's1000000-0000-0000-0000-000000000001', 't1000000-0000-0000-0000-000000000001', 'PYQ', '[UPSC CSE 2014] Which of the following is NOT guaranteed as a Fundamental Right under Part III of the Constitution of India?', 'Right to Equality', 'Right to Freedom of Religion', 'Right to Property', 'Right against Exploitation', 'C', '{"why":"Right to Property was removed from Fundamental Rights by the 44th Amendment in 1978 and made a legal right under Article 300A.","concept":"44th Constitutional Amendment Act 1978","exam_perspective":"UPSC Prelims tests core conceptual clarity and negative exclusions across constitutional, ecological, and economic dimensions.","remember":"Property is now a legal right under Article 300A, NOT a fundamental right.","related_concept":"Article 31 repeal, Article 300A"}'::jsonb, 'moderate', 2014, 'Civil Services (Preliminary) GS Paper-I', 'approved'),
